import java.lang.management.*;
import java.util.*;
import com.sun.management.HotSpotDiagnosticMXBean;
public class JvmOptionsExperiment {
    static void require(boolean ok,String message) { if(!ok)throw new AssertionError(message); }
    public static void main(String[] args) {
        require(Runtime.version().feature()==17,"target JDK17 required");
        HotSpotDiagnosticMXBean vm=ManagementFactory.getPlatformMXBean(HotSpotDiagnosticMXBean.class);
        long maximum=ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getMax();
        List<String> gc=ManagementFactory.getGarbageCollectorMXBeans().stream().map(GarbageCollectorMXBean::getName).toList();
        require(maximum==64L*1024*1024,"approved heap boundary changed");
        require(gc.contains("G1 Young Generation")&&gc.contains("G1 Old Generation"),"approved G1 policy missing");
        require(vm.getVMOption("UseContainerSupport").getValue().equals("true"),"container support disabled");
        require("training".equals(System.getProperty("application.mode"))&&"preserve".equals(System.getProperty("unrelated")),"original application properties lost");
        System.out.println("EFFECTIVE_JDK17_HEAP_67108864_G1_CONTAINER_TRUE_PROPERTIES_PRESERVED");
        List<byte[]> live=new ArrayList<>();
        try {
            for(int n=0;n<128;n++)live.add(new byte[1024*1024]);
            throw new AssertionError("bounded workload did not exhaust heap");
        } catch(OutOfMemoryError expected) {
            System.err.println("CONTROLLED_OUT_OF_MEMORY_ACTUAL:"+expected.getClass().getName());
            System.exit(42);
        }
    }
}
